import 'package:flutter/material.dart';

import 'tokens.dart';

const fontFamily = 'ChakraPetch';

/// Chakra Petch with equal-width digits, generated by tool/tabular_font.py.
const numeralFamily = 'PetchTabular';

/// Any style with tabular numerals; the cut is the full Thai+Latin font, so
/// mixed strings such as "ออกก่อน 16:45" stay in one face.
TextStyle tabular(TextStyle s) =>
    s.copyWith(fontFamily: numeralFamily, fontFamilyFallback: const [fontFamily]);

TextStyle _t(double size, double height, FontWeight w, [double tracking = 0]) => TextStyle(
      fontFamily: fontFamily,
      fontSize: size,
      height: height,
      fontWeight: w,
      letterSpacing: tracking,
      leadingDistribution: TextLeadingDistribution.even,
    );

/// Material 3 type roles in Chakra Petch. Thai stacks tone marks above and
/// vowels below the line, so body heights stay at 1.55+ and display at 1.2+.
final TextTheme fonTextTheme = TextTheme(
  displayLarge: _t(52, 1.15, FontWeight.w700, -1),
  displayMedium: _t(42, 1.2, FontWeight.w700, -.8),
  displaySmall: _t(34, 1.22, FontWeight.w700, -.5),
  headlineLarge: _t(30, 1.3, FontWeight.w700, -.3),
  headlineMedium: _t(26, 1.3, FontWeight.w700),
  headlineSmall: _t(22, 1.35, FontWeight.w700),
  titleLarge: _t(20, 1.4, FontWeight.w700),
  titleMedium: _t(16, 1.45, FontWeight.w600),
  titleSmall: _t(14, 1.45, FontWeight.w600),
  bodyLarge: _t(16, 1.6, FontWeight.w400),
  bodyMedium: _t(14, 1.6, FontWeight.w400),
  bodySmall: _t(12, 1.55, FontWeight.w400),
  labelLarge: _t(14, 1.4, FontWeight.w600),
  labelMedium: _t(12, 1.4, FontWeight.w600, .2),
  labelSmall: _t(11, 1.4, FontWeight.w600, .3),
);

